import type { Frame } from "./monsterInfo";
import { drawAngel, drawDemon, ST_H, ST_W } from "./orbs";

/**
 * Art of the monster plate (monsterBar.ts), cosmetic and generated by code like weathered.ts: six frames in the bronze
 * style of the orb rim and the skill-bar plate, painted per pixel into canvases that CSS uses as 9-slice border-images,
 * plus ornaments outside the frame (crests, fins, scroll ends, and the orb statues cut in half). Each tier is painted
 * once and cached. Also the 7x7 glyphs of the weak / resist / status icons.
 */

type RGB = [number, number, number];
interface Pal {
  /** Frame thickness in art px (shown at 2x). */
  T: number; dark: RGB; light: RGB; accent: RGB; corner?: "rivet" | "block"; double?: boolean; grain?: boolean;
  gem?: RGB; gemHi?: RGB; plateTop?: RGB; plateBot?: RGB; crest?: "shield" | "laurel" | "seal" | "skull"; side?: "statue" | "fin" | "scroll";
  statue?: "angel" | "demon"; glow?: string; name: string;
  /** Plate distance from the top of the screen, px: room for the crest and the statues above the frame. */
  top: number;
}
const PAL: Record<Frame, Pal> = {
  normal: { T: 6, dark: [70, 46, 20], light: [176, 132, 62], accent: [60, 42, 20], name: "#eadfc8", top: 8 },
  elite: { T: 7, dark: [92, 62, 26], light: [224, 178, 90], accent: [176, 138, 74], corner: "rivet", double: true, name: "#9fd8ff", top: 8 },
  champion: { T: 9, dark: [120, 84, 30], light: [255, 220, 130], accent: [230, 190, 100], corner: "block", gem: [40, 120, 200], gemHi: [150, 220, 255], crest: "shield", side: "statue", statue: "angel", glow: "rgba(255,210,120,.35)", name: "#ffd98a", top: 36 },
  named: { T: 8, dark: [70, 74, 86], light: [214, 220, 232], accent: [150, 110, 200], corner: "block", gem: [120, 60, 170], gemHi: [210, 160, 255], crest: "laurel", side: "fin", name: "#d9b8ff", top: 28 },
  quest: { T: 8, dark: [74, 46, 26], light: [170, 120, 70], accent: [214, 190, 140], grain: true, corner: "rivet", plateTop: [44, 34, 22], plateBot: [22, 16, 10], crest: "seal", side: "scroll", name: "#f0d9a0", top: 32 },
  boss: { T: 10, dark: [56, 28, 24], light: [150, 92, 72], accent: [200, 40, 28], corner: "block", gem: [150, 20, 16], gemHi: [255, 100, 60], crest: "skull", side: "statue", statue: "demon", glow: "rgba(255,60,30,.45)", name: "#ff8a6a", top: 52 },
};
/** Name colour per rank (the frame says the rest). */
export const FRAME_NAME_COLOR = Object.fromEntries(Object.entries(PAL).map(([k, v]) => [k, v.name])) as Record<Frame, string>;

const K: RGB = [20, 13, 7];
const mix = (a: RGB, b: RGB, t: number): RGB => { const u = Math.max(0, Math.min(1, t)); return [Math.round(a[0] + (b[0] - a[0]) * u), Math.round(a[1] + (b[1] - a[1]) * u), Math.round(a[2] + (b[2] - a[2]) * u)]; };
const rgb = (c: RGB) => `rgb(${c[0]},${c[1]},${c[2]})`;
function canvas(w: number, h: number) {
  const cv = document.createElement("canvas"); cv.width = w; cv.height = h;
  const g = cv.getContext("2d")!;
  return { cv, g, P: (x: number, y: number, c: RGB) => { g.fillStyle = rgb(c); g.fillRect(Math.round(x), Math.round(y), 1, 1); } };
}
type PFn = (x: number, y: number, c: RGB) => void;
function gemAt(P: PFn, x: number, y: number, o: Pal, big: boolean) {
  const r = big ? 2 : 1;
  for (let i = -r; i <= r; i++) for (let j = -r; j <= r; j++) { const d = Math.abs(i) + Math.abs(j); if (d > r) continue; P(x + i, y + j, d === r ? K : (i < 0 || j < 0) ? o.gemHi! : o.gem!); }
  if (big) P(x - 1, y - 1, [255, 255, 255]);
}

/** The 9-slice frame image (art px N x N, slice T): band, inner line, dark plate, corner rivets or gem blocks. */
function paintFrame(o: Pal): string {
  const T = o.T, N = T * 2 + 8, { cv, P } = canvas(N, N);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    const d = Math.min(x, y, N - 1 - x, N - 1 - y), light = 0.8 - (x + y) / (N * 1.5);
    let c: RGB;
    if (d === 0) c = K;
    else if (d < T - 2) {
      c = mix(o.dark, o.light, light);
      if (d === 1) c = mix(c, [255, 240, 200], 0.25);
      if (d === T - 3) c = mix(c, [0, 0, 0], 0.35);
      if (o.double && d === Math.floor(T / 2)) c = K;
      if (o.grain && (x * 7 + y * 3) % 11 === 0) c = mix(c, [0, 0, 0], 0.25);
    } else if (d === T - 2) c = K;
    else if (d === T - 1) c = o.accent;
    else c = mix(o.plateTop ?? [33, 26, 20], o.plateBot ?? [11, 9, 7], (y - T) / (N - 2 * T));
    P(x, y, c);
  }
  for (const [cx, cy, sx, sy] of [[0, 0, 1, 1], [N - 1, 0, -1, 1], [0, N - 1, 1, -1], [N - 1, N - 1, -1, -1]]) {
    const at = (dx: number, dy: number, c: RGB) => P(cx + sx * dx, cy + sy * dy, c), m = Math.floor(T / 2);
    if (o.corner === "rivet") for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) at(m + i - 1, m + j - 1, i + j < 0 ? [250, 222, 150] : i + j === 0 ? o.light : [60, 40, 18]);
    if (o.corner === "block") {
      for (let i = 0; i < T; i++) for (let j = 0; j < T; j++) at(i, j, i === 0 || j === 0 || i === T - 1 || j === T - 1 ? K : mix(o.dark, o.light, 0.8 - (i + j) / (T * 2.5)));
      gemAt((x, y, c) => at(x, y, c), m - 1, m - 1, o, T >= 9);
    }
  }
  return cv.toDataURL();
}

function paintCrest(o: Pal): HTMLCanvasElement {
  if (o.crest === "shield") {
    const { cv, P } = canvas(23, 17);
    for (let y = 0; y < 17; y++) for (let x = 0; x < 23; x++) { const w = y < 9 ? 11 : 11 - (y - 8) * 1.4, dx = Math.abs(x - 11); if (dx > w) continue; P(x, y, dx > w - 1 || y === 0 ? K : mix(o.dark, o.light, 0.9 - (x + y) / 34)); }
    gemAt(P, 11, 7, o, true); return cv;
  }
  if (o.crest === "laurel") {
    const { cv, P } = canvas(31, 15);
    for (let i = 0; i < 7; i++) for (const s of [-1, 1]) { const x = 15 + s * (4 + i * 1.6), y = 12 - i * 1.4 + i * i * 0.08; P(x, y, [60, 110, 50]); P(x + s, y - 1, [120, 190, 90]); P(x, y + 1, K); }
    gemAt(P, 15, 8, o, true); return cv;
  }
  if (o.crest === "seal") {
    const { cv, P } = canvas(17, 17);
    for (let y = 0; y < 17; y++) for (let x = 0; x < 17; x++) { const r = Math.hypot(x - 8, y - 8) + Math.sin(Math.atan2(y - 8, x - 8) * 7) * 0.7; if (r > 8) continue; P(x, y, r > 7 ? [70, 10, 10] : mix([150, 20, 20], [230, 70, 60], 0.9 - (x + y) / 26)); }
    for (const [x, y] of [[8, 5], [7, 6], [9, 6], [8, 7], [6, 8], [10, 8], [8, 9], [8, 10], [8, 11]]) P(x, y, [90, 10, 10]);
    return cv;
  }
  const { cv, P } = canvas(29, 19); // skull with horns
  const sk = ["....#######....", "...#########...", "..###########..", "..##..###..##..", "..##..###..##..", "..###########..", "...####.####...", "....#.#.#.#....", "....#######...."];
  sk.forEach((r, y) => [...r].forEach((ch, x) => ch === "#" && P(x + 7, y + 6, mix([150, 120, 100], [230, 210, 180], 1 - y / 9))));
  for (const [x, y] of [[9, 9], [10, 9], [16, 9], [17, 9]]) P(x, y, [255, 60, 30]);
  for (const s of [-1, 1]) for (let i = 0; i < 9; i++) { const x = 14 + s * (7 + i * 0.8), y = 8 - i * 0.9 + i * i * 0.06; P(x, y, [94, 40, 34]); P(x, y + 1, [160, 100, 80]); P(x + s, y + 1, K); }
  return cv;
}

function paintSide(o: Pal): HTMLCanvasElement {
  if (o.side === "scroll") {
    const { cv, P } = canvas(9, 30);
    for (let y = 0; y < 30; y++) for (let x = 0; x < 9; x++) { const k = Math.abs(x - 4) / 4.5; P(x, y, x === 0 || x === 8 || y === 0 || y === 29 ? K : mix([110, 70, 40], [230, 200, 150], 1 - k - y / 80)); }
    for (let y = 3; y < 30; y += 6) for (let x = 1; x < 8; x++) P(x, y, [90, 60, 36]);
    return cv;
  }
  const { cv, P } = canvas(12, 22); // fin
  for (let y = 0; y < 22; y++) for (let x = 0; x < 12; x++) { const w = 11 - Math.abs(y - 11) * 0.9; if (11 - x > w) continue; P(x, y, 11 - x > w - 1 ? K : mix(o.dark, o.light, 0.9 - (y + (11 - x)) / 30)); }
  gemAt(P, 8, 11, o, false);
  return cv;
}

/** The two halves of an orb statue (the angel or the demon drawn by orbs.ts) and the first painted row of the angel. */
function statueHalves(kind: "angel" | "demon") {
  const cv = document.createElement("canvas");
  (kind === "angel" ? drawAngel : drawDemon)(cv);
  const hw = ST_W / 2, half = (from: number) => { const { cv: h, g } = canvas(hw, ST_H); g.drawImage(cv, from, 0, hw, ST_H, 0, 0, hw, ST_H); return h.toDataURL(); };
  const px = cv.getContext("2d")!.getImageData(0, 0, ST_W, ST_H).data;
  let top = 0;
  find: for (let y = 0; y < ST_H; y++) for (let x = 0; x < ST_W; x++) if (px[(y * ST_W + x) * 4 + 3] > 40) { top = y; break find; }
  return { l: half(0), r: half(hw), top };
}

export interface PlateArt {
  /** Plate distance from the top of the screen, px. */
  top: number;
  /** Inline style of the plate element (border-image, glow), and the ornament elements to put inside it. */
  style: string;
  ornaments: string;
}
const cache = new Map<Frame, PlateArt>();

/** The frame and ornaments of one tier, painted on first use and kept. */
export function plateArt(frame: Frame): PlateArt {
  let a = cache.get(frame);
  if (a) return a;
  const o = PAL[frame], B = o.T * 2;
  const style = `border-width:${B}px;border-image:url(${paintFrame(o)}) ${o.T} fill / ${B}px / 0 stretch;${o.glow ? `--mb-glow:${o.glow};` : ""}`;
  let orn = "";
  if (o.crest) {
    const c = paintCrest(o), w = c.width * 2, h = c.height * 2;
    orn += `<i class="mb-orn mb-crest" style="background-image:url(${c.toDataURL()});width:${w}px;height:${h}px;margin-left:${-w / 2}px;top:${-(B + h - 10)}px"></i>`;
  }
  if (o.side === "statue") {
    const s = statueHalves(o.statue!), h = o.statue === "angel"
      // halo flush with the frame's top edge, plinth flush with its bottom edge
      ? `calc((100% + ${2 * B}px) * ${(ST_H / (ST_H - s.top)).toFixed(4)})`
      : `${ST_H * 2}px`; // the demon at 2x, plinth flush with the bottom; it rises above the top
    for (const [url, side] of [[s.l, "l"], [s.r, "r"]] as const) {
      orn += `<i class="mb-orn mb-statue ${side}" style="background-image:url(${url});height:${h};${side === "l" ? "right" : "left"}:calc(100% + ${B - 2}px);bottom:${-B}px"></i>`;
    }
  } else if (o.side) {
    const c = paintSide(o), w = c.width * 2, h = c.height * 2, url = c.toDataURL();
    for (const side of ["l", "r"]) orn += `<i class="mb-orn mb-fin ${side}" style="background-image:url(${url});width:${w}px;height:${h}px;${side === "l" ? "right" : "left"}:calc(100% + ${B - 4}px);top:calc(50% - ${h / 2}px)"></i>`;
  }
  if (frame === "champion" || frame === "named") { // a slow glint on the corner gems
    const m = Math.floor(o.T / 2), c = (m - 0.5) * 2 - B - 2;
    [[`left:${c}px;top:${c}px`, 0], [`right:${c}px;top:${c}px`, 1.1], [`left:${c}px;bottom:${c}px`, 2.2], [`right:${c}px;bottom:${c}px`, 0.6]].forEach(([p, d]) => { orn += `<i class="mb-gem" style="${p};animation-delay:${d}s"></i>`; });
  }
  a = { top: o.top, style, ornaments: orn };
  cache.set(frame, a);
  return a;
}

// ---- 7x7 icon glyphs (weak / resist elements, statuses) ----
const G: Record<string, string[]> = {
  fire: ["...#...", "..##...", "..###..", ".#####.", ".##.##.", "##...##", ".#####."],
  cold: ["...#...", ".#.#.#.", "..###..", "#######", "..###..", ".#.#.#.", "...#..."],
  poison: ["...#...", "..###..", ".#####.", ".#####.", "#######", "#######", ".#####."],
  faith: ["..###..", "..###..", "#######", "#######", "..###..", "..###..", "..###.."],
  shock: ["....##.", "...##..", "..##...", ".#####.", "...##..", "..##...", ".##...."],
  stun: ["#..#..#", ".#.#.#.", "..###..", "###.###", "..###..", ".#.#.#.", "#..#..#"],
  slow: ["#######", ".#...#.", "..#.#..", "...#...", "..#.#..", ".#####.", "#######"],
  broken: ["#######", "#.#...#", "#..#..#", ".#.#.#.", ".#..#.#", "..#.#..", "...#..."],
  burn: ["..#....", "..##.#.", ".####..", ".#####.", "#######", "#######", ".#####."],
  bleed: ["...#...", "...#...", "..###..", "..###..", ".#####.", ".#####.", "..###.."],
  boil: ["..#..#.", "...##..", "#.....#", "..#.#..", ".#...#.", "#..#...", ".#...#."],
  mark: ["...#...", "..#.#..", ".#...#.", "#.....#", ".#...#.", "..#.#..", "...#..."],
  weak: ["...#...", "...#...", "...#...", "#######", ".#####.", "..###..", "...#..."],
  steam: ["..#.#..", ".#.#...", "..#.#..", ".#.#...", "#######", ".#...#.", "..###.."],
  corrode: ["..###..", ".#...#.", "#.###.#", "#.#.#.#", "#.###.#", ".#...#.", "..###.."],
  res: ["..###..", "..#.##.", "..#....", "..#....", ".##....", "###....", ".#....."],
};
const glyphCache = new Map<string, string>();
/** Data URL of a 7x7 glyph in one colour (drawn at 2x in CSS). Unknown names give the mark glyph. */
export function glyphUrl(name: string, color: string): string {
  const key = name + color;
  let u = glyphCache.get(key);
  if (u) return u;
  const { cv, g } = canvas(7, 7);
  g.fillStyle = color;
  (G[name] ?? G.mark).forEach((r, y) => [...r].forEach((ch, x) => ch === "#" && g.fillRect(x, y, 1, 1)));
  u = cv.toDataURL();
  glyphCache.set(key, u);
  return u;
}
